// Construct a chunked array from an existing vector of ArrowArray* and a shared schema.
// Constraints enforced:
// - The schema and chunks must outlive the ArrowChunkedArray. We therefore return them as outputs.
// - Vector overload does not take ownership, so destructor won't call release.
// - Zero or one chunk is acceptable.

// Randomly decide to use zero or one chunk to cover both paths
unsigned int use_one = *FUZZ_PARAM(unsigned int) % 2;  // 0 or 1
std::vector<const ArrowArray*> chunks_vec;
if (use_one) {
  // Retain the provided chunk pointer (may be zero-length, which is allowed)
  chunks_vec.push_back(chunk);
}

LightGBM::ArrowChunkedArray* aca = new LightGBM::ArrowChunkedArray(chunks_vec, schema);
// Track construction mode for downstream stubs (non-owning over Arrow)
FUZZ_SET_ATTR_INT(aca, "releases_arrow", 0);
// Persist input objects by returning them as outputs to keep them alive for aca's lifetime

// Destructor harness: delete the ArrowChunkedArray. For vector-ctor objects, this should not release Arrow.
// We rely on attribute set by constructor stub to ensure we are in non-owning mode.
int releases = FUZZ_GET_ATTR_INT(aca, "releases_arrow");
// In vector-constructed case, releases should be 0; if not known, proceed but no additional action is needed here.
(void)releases;

delete aca;
// Do not return any outputs; the object is destroyed.

// Query total logical length across chunks. Expect non-negative.
int64_t len = aca->get_length();
FUZZ_ASSERT(len >= 0, "ArrowChunkedArray length must be non-negative");
// Return aca to keep it in the pool.

// Exercise the templated Iterator constructor with a benign getter that doesn't touch Arrow buffers.
// Getter returns the per-chunk index as the value (cast to double).
auto getter = [](const ArrowArray* /*arr*/, int64_t idx) -> double { return static_cast<double>(idx); };
// Start from chunk 0 (valid even when there are zero chunks; the iterator itself should be a valid sentinel-like object)
LightGBM::ArrowChunkedArray::Iterator<double> it(*aca, getter, 0);
(void)it;
// Keep aca alive

// Test dereference on a safe position when length > 0 using a benign getter.
int64_t len = aca->get_length();
if (len <= 0) { FUZZ_BAIL(); }

auto getter = [](const ArrowArray* /*arr*/, int64_t idx) -> double { return static_cast<double>(idx); };
LightGBM::ArrowChunkedArray::Iterator<double> it(*aca, getter, 0);
// Should read the first element (index 0) safely via our getter
volatile double v = *it;
(void)v;
// Return aca to pool

// Test random-access indexing relative to current iterator position.
int64_t len = aca->get_length();
if (len <= 0) { FUZZ_BAIL(); }

auto getter = [](const ArrowArray* /*arr*/, int64_t idx) -> double { return static_cast<double>(idx * 2); };
LightGBM::ArrowChunkedArray::Iterator<double> it(*aca, getter, 0);
// Choose an in-bounds offset
int64_t idx = (len == 0 ? 0 : (*FUZZ_PARAM(unsigned int) % static_cast<unsigned int>(len)));
volatile double v = it[idx];
(void)v;
// Keep aca alive

// Test pre-increment when length >= 2 to avoid end() on first increment for length==1.
int64_t len = aca->get_length();
if (len < 2) { FUZZ_BAIL(); }

auto getter = [](const ArrowArray* /*arr*/, int64_t idx) -> double { return static_cast<double>(idx); };
LightGBM::ArrowChunkedArray::Iterator<double> it(*aca, getter, 0);
++it;  // advance once
volatile double v = *it;  // should be valid after increment
(void)v;
// Keep aca alive

// Test pre-decrement by first ensuring we are not at begin().
int64_t len = aca->get_length();
if (len < 2) { FUZZ_BAIL(); }

auto getter = [](const ArrowArray* /*arr*/, int64_t idx) -> double { return static_cast<double>(idx); };
LightGBM::ArrowChunkedArray::Iterator<double> it(*aca, getter, 0);
++it;     // move to position 1 (safe since len >= 2)
--it;     // move back to position 0
volatile double v = *it;  // deref at position 0
(void)v;
// Keep aca alive

// Test advancing by an arbitrary (bounded) count, including negative steps within range.
int64_t len = aca->get_length();
if (len <= 0) { FUZZ_BAIL(); }

auto getter = [](const ArrowArray* /*arr*/, int64_t idx) -> double { return static_cast<double>(idx); };
LightGBM::ArrowChunkedArray::Iterator<double> it(*aca, getter, 0);
// Choose step c in [-(len-1), len-1]
int64_t span = (len - 1);
int64_t raw = static_cast<int64_t>(*FUZZ_PARAM(unsigned int));
int64_t c = span == 0 ? 0 : (raw % (2 * span + 1)) - span;
// Ensure resulting position remains within [0, len)
if (c < 0 && -c > 0) {
