  int64_t fwd = -c;
  if (fwd >= len) { FUZZ_BAIL(); }
  it += fwd;
  it += c;  // c is negative, net move back
} else {
  if (c >= len) { FUZZ_BAIL(); }
  it += c;
}
volatile double v = *it;
(void)v;
// Keep aca alive

// Test distance between two iterators over the same array.
int64_t len = aca->get_length();
// Allow zero-length: distance of begin to begin should be zero even for empty arrays
auto getter = [](const ArrowArray* /*arr*/, int64_t idx) -> double { return static_cast<double>(idx); };
