              char* /*output*/, LightGBM::comm_size_t /*output_size*/) {};
if (LGBM_NetworkInitWithFunctions(1, 0, reinterpret_cast<void*>(rs), reinterpret_cast<void*>(ag)) != 0) { FUZZ_BAIL(); }
int rc = LGBM_NetworkFree();
if (rc != 0) { FUZZ_BAIL(); }
// Validation: Establishes a no-op init context to guarantee NetworkFree succeeds without real sockets.

// Set a small thread cap and accept success
int num_threads = static_cast<int>(*FUZZ_PARAM(unsigned int) % 8) + 1; // 1..8
int rc = LGBM_SetMaxThreads(num_threads);
if (rc != 0) { FUZZ_BAIL(); }
// Validation: Ensures API accepts small, valid thread cap.

// Query current max threads
int out = -2;
int rc = LGBM_GetMaxThreads(&out);
if (rc != 0) { FUZZ_BAIL(); }
// out can be -1 (default) or positive; ensure not less than -1
FUZZ_ASSERT(out >= -1, "Invalid thread cap value");
// Validation: Confirms getter returns a sane value.

// Provide a fuzz message (will be truncated internally to 512)
std::string s = FUZZ_PARAM_STR();
LGBM_SetLastError(s.c_str());
// Optional check via getter that a string is present
const char* got = LGBM_GetLastError();
FUZZ_ASSERT(got != nullptr, "LastError should return non-null after set");
// Validation: Sets thread-local error message and validates retrievability.

// Create a GBDT-based booster via the factory and downcast to GBDTBase.
// We avoid initialization/training here; downstream stubs should tolerate models with zero trees.
const char* filename = "";  // no model file; create an empty booster of the requested type
std::string type = "gbdt";   // ensures factory returns a tree-based implementation in typical builds
LightGBM::Boosting* boosting = LightGBM::Boosting::CreateBoosting(type, filename);
if (!boosting) { FUZZ_BAIL(); }
// Downcast to GBDTBase to expose leaf getters/setters
LightGBM::GBDTBase* gbdt = dynamic_cast<LightGBM::GBDTBase*>(boosting);
if (!gbdt) {
  // Factory might not have produced a GBDT-based implementation in this build
  FUZZ_BAIL();
}
// Track type for downstream validation
FUZZ_SET_ATTR_STR(gbdt, "boosting_type", type.c_str());
// Validation: gbdt is non-null if we reach here. No training performed.

// Construct a chunked array from an existing vector of ArrowArray* and a shared schema.
// Constraints enforced:
// - The schema and chunks must outlive the ArrowChunkedArray. We therefore return them as outputs.
// - Vector overload does not take ownership, so destructor won't call release.
// - Zero or one chunk is acceptable.

// Randomly decide to use zero or one chunk to cover both paths
unsigned int use_one = *FUZZ_PARAM(unsigned int) % 2;  // 0 or 1
std::vector<const ArrowArray*> chunks_vec;
if (use_one) {
  // Retain the provided chunk pointer (may be zero-length, which is allowed)
  chunks_vec.push_back(chunk);
}

LightGBM::ArrowChunkedArray* aca = new LightGBM::ArrowChunkedArray(chunks_vec, schema);
// Track construction mode for downstream stubs (non-owning over Arrow)
FUZZ_SET_ATTR_INT(aca, "releases_arrow", 0);
// Persist input objects by returning them as outputs to keep them alive for aca's lifetime
// Validation: aca is constructed; inputs are returned to maintain lifetime assumptions.

// Allocate and minimally initialize an ArrowArray following Arrow C Data Interface semantics.
// We set a small length, zero/null buffers, and valid release callback.
ArrowArray* array = new ArrowArray();
int64_t length = static_cast<int64_t>(*FUZZ_PARAM(unsigned int) % 64);  // keep small
array->length = length;
array->null_count = 0;
array->offset = 0;
// Decide a small buffer count (0..2) but we won't allocate actual data buffers; only the holder array.
int64_t nbuf = static_cast<int64_t>(*FUZZ_PARAM(unsigned int) % 3);
array->n_buffers = nbuf;
array->n_children = 0;

// Allocate holder arrays (buffers/children) owned by this ArrowArray
if (nbuf > 0) {
  const void** bufs = new const void*[static_cast<size_t>(nbuf)];
  for (int64_t i = 0; i < nbuf; ++i) bufs[i] = nullptr;  // no actual data
  array->buffers = bufs;
} else {
  array->buffers = nullptr;
}
array->children = nullptr;
array->dictionary = nullptr;
array->private_data = nullptr;

// Release callback frees holder arrays but not the ArrowArray struct itself.
auto release_array = [](ArrowArray* self){
  if (!self || !self->release) return;
  if (self->buffers) { delete[] self->buffers; self->buffers = nullptr; }
  if (self->children) { delete[] self->children; self->children = nullptr; }
  self->dictionary = nullptr;
  self->n_buffers = 0;
  self->n_children = 0;
  // Prevent double release
  self->release = nullptr;
};
array->release = +release_array;

// Mark live
FUZZ_SET_ATTR_INT(array, "arrow_array_alive", 1);
// Validation: array allocated, length small, release installed; no external buffers to manage.

// Allocate and initialize an ArrowSchema following Arrow C Data Interface semantics.
// We construct a primitive int32 schema with no children/dictionary and install a valid release callback.

ArrowSchema* schema = new ArrowSchema();

// Use simple, valid format string for a primitive type: "i" => int32
std::string fmt = "i";
// Random name/metadata, constrained in size to keep allocations small
std::string n = FUZZ_PARAM_STR();
if (n.size() > 64) n.resize(64);
std::string md = FUZZ_PARAM_STR();
if (md.size() > 128) md.resize(128);

// Allocate owned C-strings for fields; release callback will free them
char* fmt_c = new char[fmt.size() + 1]; std::memcpy(fmt_c, fmt.c_str(), fmt.size() + 1);
char* name_c = new char[n.size() + 1]; std::memcpy(name_c, n.c_str(), n.size() + 1);
char* meta_c = new char[md.size() + 1]; std::memcpy(meta_c, md.c_str(), md.size() + 1);

schema->format = fmt_c;
schema->name = name_c;
schema->metadata = meta_c;
schema->flags = 0;                // no special flags
schema->n_children = 0;           // primitive type => no children
schema->children = nullptr;
schema->dictionary = nullptr;
schema->private_data = nullptr;   // not used here

// Non-capturing lambda as release callback: frees owned strings and any allocated child holder array.
// It does NOT delete the ArrowSchema struct itself (caller owns that memory).
auto release_schema = [](ArrowSchema* self){
  if (!self || self->release == nullptr) { return; }
  if (self->format) { delete[] self->format; self->format = nullptr; }
  if (self->name) { delete[] self->name; self->name = nullptr; }
  if (self->metadata) { delete[] self->metadata; self->metadata = nullptr; }
  // If a children holder array had been allocated, free it here (we don't allocate any in this stub)
  if (self->children) { delete[] self->children; self->children = nullptr; }
  // Do not traverse or free dictionary/children entries; producers usually manage nested lifetimes.
  self->dictionary = nullptr;
  self->n_children = 0;
  // Prevent double-release
  self->release = nullptr;
};
schema->release = +release_schema;

// Track state for downstream consumers
FUZZ_SET_ATTR_INT(schema, "arrow_schema_alive", 1);
FUZZ_SET_ATTR_INT(schema, "arrow_schema_has_children", 0);
// Validation: schema is allocated, fields initialized, and release callback installed.

