import random
import io
from typing import List

# We generate plausible LightGBM text datasets that its parsers can read from a fuzz file.
# Target stubs:
# - Parser::CreateParser(filename, header, num_features, label_idx, precise)
# - DatasetLoader ctor may read filename for header/config
# - LGBM_DatasetCreateFromFile(filename, params)
# Thus, filename should point to content that looks like a LightGBM-compatible dataset.
# We will emit a single bytes blob intended to be used as the file content behind FUZZ_PARAM_FILENAME.
# The content will include, near the beginning, a LightGBM parameter line (when used as params string) is separate,
# but we cannot control FUZZ_PARAM_STR here; however, the file itself should parse as dataset text.
# We support multiple dialects in one file by placing plausible header and rows.

DELIMS = [",", "\t", " ", ";", "|"]

CATS = ["A", "B", "C", "X", "Y", "Z", "cat", "dog", "mouse", "u1", "u2", "u3"]


def _rand_delim(r: random.Random) -> str:
    return r.choice(DELIMS)


def _make_header(r: random.Random, n_features: int, include_label: bool, label_name: str = "label") -> str:
    cols = []
    if include_label:
        cols.append(label_name)
    for i in range(n_features):
        # mix of names
        base = r.choice([f"f{i}", f"feature_{i}", f"col{i}", f"x{i}"])
        cols.append(base)
    return cols


def _num_token(r: random.Random) -> str:
    # produce varied numeric tokens
    choice = r.randint(0, 8)
    if choice == 0:
        return "0"
    if choice == 1:
        return "1"
    if choice == 2:
        return str(r.randint(-3, 9))
    if choice == 3:
        return f"{r.uniform(-5, 5):.6f}"
    if choice == 4:
        return f"{r.random():.10f}"
    if choice == 5:
        return "NaN"
    if choice == 6:
        return "inf" if r.random() < 0.5 else "-inf"
    if choice == 7:
        return f"{r.randint(0, 1000)}"
    return f"{r.gauss(0, 1):.6f}"


def _cat_token(r: random.Random) -> str:
    if r.random() < 0.8:
        return r.choice(CATS)
    # numeric-looking categorical
    return str(r.randint(0, 5))


def _make_row(r: random.Random, n_features: int, label_first: bool, delim: str, cat_mask: List[bool]) -> str:
    fields: List[str] = []
    # label binary/regression
    label = None
    if r.random() < 0.5:
        # binary label 0/1 or -1/1
        if r.random() < 0.5:
            label = str(r.randint(0, 1))
        else:
            label = str(r.choice([-1, 1]))
    else:
        label = _num_token(r)
    # generate features
    feats = []
    for i in range(n_features):
        if cat_mask[i]:
            tok = _cat_token(r)
        else:
            tok = _num_token(r)
        feats.append(tok)
    if label_first:
        fields.append(label)
        fields.extend(feats)
    else:
        fields.extend(feats)
        fields.append(label)
    return delim.join(fields)


def _maybe_sparse_row(r: random.Random, n_features: int) -> str:
    # Create LibSVM-like sparse line: "label index:value ..."
    label = str(r.randint(0, 1)) if r.random() < 0.6 else _num_token(r)
    parts = [label]
    # choose some indices
    k = max(1, int(r.paretovariate(2.5)) % max(2, n_features))
    used = sorted(set(r.randint(0, n_features - 1) for _ in range(k)))
    for idx in used:
        val = _num_token(r)
        # 1-based indices common in LibSVM
        parts.append(f"{idx+1}:{val}")
    return " ".join(parts)


def _make_block_csv(r: random.Random) -> str:
    # Create a CSV/TSV block with optional header
    n_features = r.randint(1, 12)
    delim = _rand_delim(r)
    header = r.random() < 0.6
    label_first = r.random() < 0.8  # LightGBM default expects label first if present
    # randomly choose categorical mask
    cat_mask = [r.random() < 0.2 for _ in range(n_features)]

    lines = []
    if header:
        cols = _make_header(r, n_features, include_label=True if label_first else False)
        # sometimes put label at end and name it explicitly
        if not label_first:
            cols.append("label")
        lines.append(delim.join(cols))
    n_rows = r.randint(5, 60)
    for _ in range(n_rows):
        lines.append(_make_row(r, n_features, label_first, delim, cat_mask))
    return "\n".join(lines)


def _make_block_sparse(r: random.Random) -> str:
    n_features = r.randint(4, 32)
    n_rows = r.randint(5, 60)
    lines = []
    # Optional header-like comment
    if r.random() < 0.3:
        lines.append(f"# libsvm sparse format with {n_features} features")
    for _ in range(n_rows):
        lines.append(_maybe_sparse_row(r, n_features))
    return "\n".join(lines)


def _make_block_categorical_csv(r: random.Random) -> str:
    # Explicit categorical-heavy CSV with header
    n_features = r.randint(2, 10)
    delim = _rand_delim(r)
    cols = ["label"] + [f"cat{i}" for i in range(n_features)]
    lines = [delim.join(cols)]
    for _ in range(r.randint(5, 40)):
        row = [str(r.randint(0, 1))] + [
            _cat_token(r) if r.random() < 0.9 else _num_token(r) for _ in range(n_features)
        ]
        lines.append(delim.join(row))
    return "\n".join(lines)


def _make_params_hint(r: random.Random) -> str:
    # Some LightGBM CLI parameter lines, placed as a comment so parsers ignore
    params = {
        "max_bin": str(r.choice([255, 127, 63])),
        "header": str(r.choice(["true", "false", "0", "1"])),
        "label_column": r.choice(["name=label", "0", "last"]),
        "categorical_feature": r.choice(["name:cat0,cat1", "0,2", ""]),
        "two_round": r.choice(["true", "false"]),
        "precise_float_parser": r.choice(["true", "false"]),
    }
    kv = " ".join(f"{k}={v}" for k, v in params.items() if v)
    return f"# lightgbm_parameters {kv}"


def generate(seed: int) -> bytes:
    r = random.Random(seed)
    # Choose a layout strategy
    strategies = ["csv", "sparse", "cat_csv", "mixed"]
    strategy = r.choice(strategies)

    blocks: List[str] = []
    # Always include a parameter hint comment at top to be harmless for parsers but useful context
    blocks.append(_make_params_hint(r))

    if strategy == "csv":
        blocks.append(_make_block_csv(r))
    elif strategy == "sparse":
        blocks.append(_make_block_sparse(r))
    elif strategy == "cat_csv":
        blocks.append(_make_block_categorical_csv(r))
    else:
        # mixed: multiple blocks separated by blank lines; parsers typically read sequentially
        blocks.append(_make_block_csv(r))
        blocks.append("")
        blocks.append(_make_block_sparse(r))

    # Optionally append some trailing whitespace and a final newline
    if r.random() < 0.7:
        blocks.append("")

    data = "\n".join(blocks)
    # Ensure size limit
    b = data.encode("utf-8")[:4096]
    return b
